INSERT INTO oto_domain (code, label, definition) VALUES ('OrganizationalStructure', 'Organizational structure as code', 'The human and structural anatomy of the organization: structural truth is not inferred, it is declared.');
INSERT INTO oto_domain (code, label, definition) VALUES ('PolicyAsCode', 'Policy as code', 'Organizational intent as enforceable logic rather than prose: policy is not static text, it is executable intent.');
INSERT INTO oto_domain (code, label, definition) VALUES ('ProcessAndWorkflow', 'Process and workflow as code', 'How work actually flows: processes are graphs, tasks are bound to roles, decisions have criteria and authority, and failure paths are first-class.');
INSERT INTO oto_domain (code, label, definition) VALUES ('InfrastructureAndPlatform', 'Infrastructure as code and platform truth', 'The technical substrate on which operations run: infrastructure is declarative and inspectable, and identity and access are graph-connected to roles and policies.');
INSERT INTO oto_domain (code, label, definition) VALUES ('EvidenceAndTelemetry', 'Evidence and telemetry as truth anchors', 'The domain that grounds the ontology in observable reality: evidence is not documentation, it is proof, immutable, attributable, linked to what it supports and bounded in time and scope.');
INSERT INTO oto_domain (code, label, definition) VALUES ('ExternalObligations', 'External obligations and normative frameworks', 'The world the organization operates in: external requirements never stand alone, they map to internal policies, controls and evidence, and traceability is bidirectional.');
INSERT INTO oto_domain (code, label, definition) VALUES ('ChangeAndMemory', 'Change, versioning and organizational memory', 'How the organization evolves: every change has authorship, intent and measurable impact, and rollback is possible and explicit; organizations gain memory, not just history.');
INSERT INTO oto_domain (code, label, definition) VALUES ('SimulationAndTesting', 'Simulation, testing and counterfactuals', 'Safe experimentation: changes are modeled before execution, policies are tested before enforcement, and governance moves from reactive to predictive.');
INSERT INTO oto_domain (code, label, definition) VALUES ('UnifyingGraph', 'Unifying graph model', 'All domains resolve into a single typed graph whose nodes are declared entities and whose edges are explicit relationships with semantics, direction and constraints: the graph is the system of record.');

